(async()=>{
const FILES={input:{name:'sales_incident_inputs.zip',b64:''},golden:{name:'sales_incident_report.zip',b64:''}};
const REVIEW="This round fixes the six rubric findings. Coverage: a new criterion grades the July 20 backfill after its first divergence (zero-row customer output, reuse of the July 19 fact artifact, mixed-freshness aggregation and its completed publication) and its distinction from the scheduled run's blocked publication, the retry and the July 21 rejection; one golden paragraph in the backfill timeline was extended so the report states this explicitly, using artifact_manifest.csv, partition_state.csv and task_instances.csv. Determinacy: criterion 13 now accepts any appropriate supplied record for the skipped publication, the empty-artifact criterion credits either failing the producing task or an explicit empty state with a downstream non-empty gate, the recovery criterion accepts regeneration or promotion of the already-rebuilt retry lineage, and the cross-run reuse criterion accepts a ban or rigorously validated reuse. Mechanics: the filename-only criterion was removed. The prompt and input files are unchanged.";
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const txt=e=>(e.textContent||'').replace(/\s+/g,' ').trim();
const toFile=f=>{const bin=atob(f.b64);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return new File([a],f.name,{type:'application/zip'});};
const near=(el,re,stop)=>{let c=el;for(let k=0;k<8&&c;k++){c=c.parentElement;if(c&&re.test(txt(c))&&!(stop&&stop.test(txt(c))))return c;}return null;};
const fileInputs=[...document.querySelectorAll('input[type=file]')];
console.log('file inputs on page:',fileInputs.length);
const pick=(re,stop)=>fileInputs.find(i=>near(i,re,stop));
const upload=async(inputEl,f,label)=>{if(!inputEl){console.error('Uploader not found for',label);return;}
  const dt=new DataTransfer();dt.items.add(toFile(f));inputEl.files=dt.files;
  inputEl.dispatchEvent(new Event('input',{bubbles:true}));inputEl.dispatchEvent(new Event('change',{bubbles:true}));
  const zone=inputEl.closest('[role=presentation],[role=button],div');
  if(zone){try{zone.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));}catch(e){}}
  console.log('Uploaded',f.name,'to',label);await sleep(2500);};
await upload(pick(/Input File Uploader/i,/Golden Solution File Uploader/i),FILES.input,'Input File Uploader');
await upload(pick(/Golden Solution File Uploader/i,/Input File Uploader/i),FILES.golden,'Golden Solution File Uploader');
// multi-modal = No
const q=[...document.querySelectorAll('body *')].find(e=>/^Are the input files multi-modal\?/i.test(txt(e))&&e.children.length<3);
let block=q;while(block&&!block.querySelector('input[type=radio],[role=radio]'))block=block.parentElement;
if(block){const opts=[...block.querySelectorAll('label,[role=radio],button,div,span')].filter(e=>txt(e)==='No');
  const r=[...block.querySelectorAll('input[type=radio]')].find(x=>/no/i.test(x.value)||(x.closest('label')&&txt(x.closest('label'))==='No'));
  (r||opts[opts.length-1]).click();console.log('Multi-modal set to No');}else console.error('Multi-modal question not found');
// review
const head=[...document.querySelectorAll('body *')].find(e=>/^Briefly summarize the changes made/i.test(txt(e))&&e.children.length<3);
let rb=head;while(rb&&!rb.querySelector('textarea'))rb=rb.parentElement;
if(rb){const ta=rb.querySelector('textarea');ta.focus();Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(ta,REVIEW);ta.dispatchEvent(new Event('input',{bubbles:true}));ta.dispatchEvent(new Event('change',{bubbles:true}));ta.blur();console.log('Review',ta.value===REVIEW?'filled':'NOT SET');}else console.error('Review box not found');
console.log('ALL DONE. Check the two uploads show the file names, and that No is selected.');
})();